/// <summary>
/// Data contract class as a response for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
class METSalesOrderResponseContract extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_result">Result of the cancellation</param>
    /// <param name = "_mssage">Message Result</param>
    /// <returns>new contract</returns>
    public static METSalesOrderResponseContract newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METSalesOrderResponseContract salesOrderResponse = new METSalesOrderResponseContract();

        salesOrderResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        salesOrderResponse.parmMessage(_message);

        return salesOrderResponse;
    }
